  "settings.modelProvider.fieldHelp": "O {field}",
  "settings.modelProvider.help.contextWindow": "Kapacitet konteksta koji model može obraditi odjednom, u tokenima. ZAICODE ga koristi za upravljanje kontekstom.\nNemoj premašiti stvarno ograničenje modela.",
  "settings.modelProvider.help.maxOutputTokens": "Najveći broj tokena koji jedan zahtjev modelu smije generirati.\nNemoj premašiti stvarno ograničenje modela.",
  "settings.modelProvider.help.inputModalities": "Postavi vrste sadržaja koje model može primati:\n\n- **Tekst**: prima tekstualni sadržaj. Obavezno.\n- **Slike**: prima slikovni sadržaj.\n- **Video**: prima videosadržaj.\n- **PDF**: prima PDF dokumente izravno.",
  "settings.modelProvider.help.outputModalities": "Vrsta sadržaja odgovora modela. Trenutačno je podržan samo tekst.",
  "settings.modelProvider.help.capabilities": "- **Strukturirani izlaz**: podržava ograničenja JSON Schema nad izlaznim poljima, vrstama i strukturom.\n- **Ugrađeno web pretraživanje**: podržava ugrađenu sposobnost web pretraživanja u API-u modela.\n- **Sistemske poruke usred razgovora**: podržava umetanje sistemskih uputa tijekom razgovora.\n\nNemoj omogućavati mogućnosti koje model ne podržava.",
  "settings.modelProvider.help.reasoningLevelsOrdered": "Postavi razine razmišljanja dostupne u chatu. **Moraju biti poredane od najniže do najviše razine razmišljanja**.\nNemoj konfigurirati razine razmišljanja koje model ne podržava.",
  "settings.modelProvider.help.reasoningLevelMapping": "Koristi CEL izraz za mapiranje trenutne razine razmišljanja, `reasoningLevel`, u polja zahtjeva API-u modela. JSON objekt koji izraz vrati spaja se u tijelo odlazećeg zahtjeva.",
  "settings.modelProvider.help.advanced": "**MFJS shema alata**: omogućuje kompatibilnost sa Moonshot Flavored JSON Schema, koju često koristi Kimi API tvrtke Moonshot. Omogući samo ako API modela zahtijeva taj format.",
  "settings.modelProvider.help.followRecommendedConfig": "Odgovara preporučenoj konfiguraciji prema ID-u modela, Base URL-u i API formatu. ZAICODE stalno ažurira preporuke i automatski ih sinkronizira s tobom.\nKada ručno promijeniš postavku, ta postavka postaje ručno upravljana i prestaje pratiti ažuriranja preporuka; ostale postavke i dalje upravlja pametna konfiguracija.",
