  "zaicode.help.step1": "1. Agenati i načini rada (lijevo): Hunter, Tester, Cleaner, Wikier, Translator i prilagođene uloge. Klikni način rada da ga aktiviraš, pa dodijeli zadatke u redu za pokretanje agenta.",
